"use client";

import React, { useState } from "react";

export function ReviewHelpfulVote() {
  const [votes, setVotes] = useState(24);
  const [voted, setVoted] = useState(false);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-4 rounded-xl shadow-lg select-none font-sans text-foreground flex items-center justify-between">
      <span className="text-xs text-muted-foreground/60">Was this review helpful to you?</span>
      <button 
        onClick={() => {
          if (!voted) {
            setVotes(votes + 1);
            setVoted(true);
          }
        }}
        className={`px-3 py-1 text-[10px] font-bold rounded-lg border transition-all ${
          voted ? "bg-emerald-600 border-transparent text-white" : "bg-secondary border-border hover:bg-secondary/60 text-foreground"
        }`}
      >
        Yes, Helpful ({votes})
      </button>
    </div>
  );
}
